import rosterkit.errors


def seating_rows(students, seats_per_row):
    if seats_per_row <= 0:
        raise rosterkit.errors.ProjectError('seats per row must be positive')
    if not students:
        raise rosterkit.errors.ProjectError('no students to seat')
    ordered = sorted(students, key=lambda s: (s.last_name, s.first_name))
    lines = []
    for start in range(0, len(ordered), seats_per_row):
        names = []
        for student in ordered[start:start + seats_per_row]:
            names.append(student.display_name)
        lines.append('Row {}: {}'.format(start // seats_per_row + 1, ' | '.join(names)))
    return lines
EOF
cat > tests/test_seating.py <<'EOF'
import unittest

import rosterkit.errors
import rosterkit.models
import rosterkit.seating


def make(last, first):
    return rosterkit.models.Student('id', last, first, 'A')


class SeatingTests(unittest.TestCase):
    def test_rows_sorted_by_last_name(self):
        students = [make('Halloway', 'Juno'), make('Dunmere', 'Piet'), make('Zed', 'Amy')]
        self.assertEqual(
            rosterkit.seating.seating_rows(students, 2),
            ['Row 1: Dunmere, Piet | Halloway, Juno', 'Row 2: Zed, Amy'],
        )

    def test_bad_seat_count_raises(self):
        for seats in (0, -1):
            with self.assertRaises(rosterkit.errors.ProjectError):
                rosterkit.seating.seating_rows([make('A', 'B')], seats)

    def test_no_students_raises(self):
        with self.assertRaises(rosterkit.errors.ProjectError):
            rosterkit.seating.seating_rows([], 3)
